// src/pages/StudentDashboard.jsx
import { useState, useEffect, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";

// Reusable Card Component
const Card = ({ title, children }) => (
  <div
    style={{
      background: "#fff",
      padding: "20px",
      borderRadius: "12px",
      boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
      marginBottom: "20px",
    }}
  >
    <h2 style={{ marginBottom: "15px", color: "#007bff" }}>{title}</h2>
    {children}
  </div>
);

export default function StudentDashboard() {
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [activeTab, setActiveTab] = useState("Candidates");

  const [candidates, setCandidates] = useState([]);
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});
  const [elections, setElections] = useState([]);
  const [selectedElection, setSelectedElection] = useState(null);
  const [myCandidacy, setMyCandidacy] = useState(null);

  const [formName, setFormName] = useState("");
  const [formPosition, setFormPosition] = useState("");
  const [formParty, setFormParty] = useState("");
  const [formDocuments, setFormDocuments] = useState([]);
  const [formLoading, setFormLoading] = useState(false);
  const [formError, setFormError] = useState(null);

  const { logout } = useContext(AuthContext);
  const navigate = useNavigate();

  // --- Utility functions ---
  const statusStyle = (bgColor, textColor) => ({
    backgroundColor: bgColor,
    color: textColor,
    padding: "4px 10px",
    borderRadius: "6px",
    fontWeight: "bold",
    fontSize: "0.9rem",
  });

  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    }
  };

  // --- API calls ---
  const fetchCandidates = async () => {
    try {
      const res = await api.get("/candidates");
      setCandidates(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchElections = async () => {
    try {
      const res = await api.get("/elections");
      const sorted = res.data
        .map((e) => ({
          ...e,
          startsAt: new Date(e.startsAt),
          endsAt: new Date(e.endsAt),
          isVotingOpen: e.votingOpen,
          hasEnded: e.hasEnded,
        }))
        .sort((a, b) => b.startsAt - a.startsAt);

      setElections(sorted);

      if (sorted.length > 0) {
        const firstElection = sorted[0];
        setSelectedElection(firstElection.id);

        if (firstElection.hasEnded) fetchResults(firstElection.id);
      }
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchResults = async (electionId) => {
    try {
      const res = await api.get("/results", { params: { electionId } });
      setResults(res.data.positionResults || {});
      setWinners(res.data.winners || {});
      setSelectedElection(electionId);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchMyCandidacy = async () => {
    try {
      const res = await api.get("/candidates/my-candidacy");
      if (res.data) {
        setMyCandidacy({
          ...res.data,
          status:
            res.data.approved === null
              ? "pending"
              : res.data.approved
              ? "approved"
              : "rejected",
        });
      } else {
        setMyCandidacy(null);
      }
    } catch (err) {
      if (err.response?.status === 404) setMyCandidacy(null);
      else handleApiError(err);
    }
  };

  // --- Reapply candidacy ---
  const reapplyCandidacy = async () => {
    if (!myCandidacy) return;

    try {
      await api.post("/candidates/reapply", { id: myCandidacy.id });

      // Update local state to reflect "pending"
      setMyCandidacy((prev) => ({
        ...prev,
        status: "pending",
        rejectionComment: null,
      }));
    } catch (err) {
      console.error("Failed to reapply:", err);
      handleApiError(err);
    }
  };

  // --- Submit Candidacy Form ---
  const handleFileChange = (e) => {
    setFormDocuments([...e.target.files]);
  };

  const handleSubmitCandidacy = async (e) => {
    e.preventDefault();
    if (!formName || !formPosition) {
      setFormError("Name and Position are required.");
      return;
    }

    const formData = new FormData();
    formData.append("name", formName);
    formData.append("position", formPosition);
    if (formParty) formData.append("party", formParty);
    formDocuments.forEach((doc) => formData.append("documents", doc));

    try {
      setFormLoading(true);
      const res = await api.post("/candidates", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      setMyCandidacy({
        ...res.data.candidate,
        status: "pending",
        rejectionComment: null,
      });

      setFormName("");
      setFormPosition("");
      setFormParty("");
      setFormDocuments([]);
      setFormError(null);
    } catch (err) {
      console.error(err);
      setFormError(err.response?.data?.error || "Failed to submit candidacy.");
    } finally {
      setFormLoading(false);
    }
  };

  useEffect(() => {
    fetchCandidates();
    fetchElections();
    fetchMyCandidacy();
  }, []);

  // --- Render ---
  const renderContent = () => {
    const activeElection = elections.find((el) => el.id === selectedElection);

    switch (activeTab) {
      case "Candidates":
        if (!activeElection)
          return (
            <Card title="Approved Candidates">
              <p>No active election found.</p>
            </Card>
          );
        if (candidates.length === 0)
          return (
            <Card title="Approved Candidates">
              <p>No candidates yet.</p>
            </Card>
          );
        if (!activeElection.isVotingOpen)
          return (
            <Card title="Approved Candidates">
              <p>Voting is not open yet.</p>
            </Card>
          );

        return (
          <Card title="Approved Candidates">
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr style={{ background: "#f1f1f1" }}>
                  <th style={{ padding: "8px" }}>Name</th>
                  <th style={{ padding: "8px" }}>Position</th>
                  <th style={{ padding: "8px" }}>Party</th>
                </tr>
              </thead>
              <tbody>
                {candidates.map((c) => (
                  <tr key={c.id} style={{ borderTop: "1px solid #eee" }}>
                    <td style={{ padding: "8px" }}>{c.name}</td>
                    <td style={{ padding: "8px" }}>{c.position}</td>
                    <td style={{ padding: "8px" }}>{c.party || "-"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </Card>
        );

      case "Results":
        if (!activeElection)
          return (
            <Card title="Election Results">
              <p>No active election found.</p>
            </Card>
          );
        if (!activeElection.hasEnded)
          return (
            <Card title="Election Results">
              <p>Results will be available after the election ends.</p>
            </Card>
          );

        return (
          <Card title="Election Results">
            {Object.keys(results).length === 0 ? (
              <p>No results available.</p>
            ) : (
              Object.keys(results).map((pos) => (
                <div key={pos} style={{ marginBottom: "20px" }}>
                  <h3>{pos}</h3>
                  <table style={{ width: "100%", borderCollapse: "collapse" }}>
                    <thead>
                      <tr style={{ background: "#f1f1f1" }}>
                        <th style={{ padding: "8px" }}>Candidate</th>
                        <th style={{ padding: "8px" }}>Party</th>
                        <th style={{ padding: "8px", textAlign: "center" }}>Votes</th>
                      </tr>
                    </thead>
                    <tbody>
                      {results[pos]?.map((c) => (
                        <tr key={c.id}>
                          <td style={{ padding: "8px" }}>{c.name}</td>
                          <td style={{ padding: "8px" }}>{c.party || "-"}</td>
                          <td style={{ padding: "8px", textAlign: "center" }}>{c.votes}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  {winners[pos] && (
                    <p style={{ fontWeight: "bold", color: "green" }}>
                      Winner: {winners[pos].name} ({winners[pos].party || "-"})
                    </p>
                  )}
                </div>
              ))
            )}
          </Card>
        );

      case "RegisterCandidacy":
        return (
          <Card title="My Candidacy Status">
            {!myCandidacy ? (
              <>
                <p>You haven’t filed for candidacy yet. Submit below:</p>
                <form
                  onSubmit={handleSubmitCandidacy}
                  style={{ display: "flex", flexDirection: "column", gap: "15px" }}
                >
                  {formError && <p style={{ color: "red" }}>{formError}</p>}
                  <input
                    type="text"
                    placeholder="Full Name"
                    value={formName}
                    onChange={(e) => setFormName(e.target.value)}
                    required
                  />
                  <input
                    type="text"
                    placeholder="Position"
                    value={formPosition}
                    onChange={(e) => setFormPosition(e.target.value)}
                    required
                  />
                  <input
                    type="text"
                    placeholder="Party (optional)"
                    value={formParty}
                    onChange={(e) => setFormParty(e.target.value)}
                  />
                  <input
                    type="file"
                    multiple
                    onChange={handleFileChange}
                    accept=".pdf,.jpg,.jpeg,.png"
                  />
                  <button
                    type="submit"
                    style={{
                      padding: "10px 20px",
                      background: "#007bff",
                      color: "#fff",
                      border: "none",
                      borderRadius: "6px",
                      cursor: "pointer",
                    }}
                    disabled={formLoading}
                  >
                    {formLoading ? "Submitting..." : "Submit Candidacy"}
                  </button>
                </form>
              </>
            ) : (
              <>
                <p>
                  <strong>Position:</strong> {myCandidacy.position}
                </p>
                <p>
                  <strong>Status:</strong>{" "}
                  {myCandidacy.status === "pending" && (
                    <span style={statusStyle("#ffc107", "#000")}>Pending</span>
                  )}
                  {myCandidacy.status === "approved" && (
                    <span style={statusStyle("#28a745", "#fff")}>Approved</span>
                  )}
                  {myCandidacy.status === "rejected" && (
                    <span style={statusStyle("#dc3545", "#fff")}>Rejected</span>
                  )}
                </p>

                {myCandidacy.status === "rejected" && myCandidacy.rejectionComment && (
                  <>
                    <p style={{ color: "#dc3545", marginTop: "10px" }}>
                      <strong>Admin Comments:</strong> {myCandidacy.rejectionComment}
                    </p>
                    <button
                      onClick={reapplyCandidacy}
                      style={{
                        marginTop: "10px",
                        padding: "8px 16px",
                        background: "#ffc107",
                        color: "#000",
                        border: "none",
                        borderRadius: "6px",
                        cursor: "pointer",
                        fontWeight: "bold",
                      }}
                    >
                      Reapply
                    </button>
                  </>
                )}
              </>
            )}
          </Card>
        );

      default:
        return null;
    }
  };

  return (
    <div
      style={{
        display: "flex",
        minHeight: "100vh",
        fontFamily: "Arial, sans-serif",
        background: "#f4f6f8",
      }}
    >
      {/* Sidebar */}
      <aside
        style={{
          width: sidebarOpen ? "220px" : "60px",
          background: "#343a40",
          color: "#fff",
          transition: "width 0.3s",
          paddingTop: "20px",
        }}
      >
        <button
          onClick={() => setSidebarOpen(!sidebarOpen)}
          style={{
            background: "none",
            border: "none",
            color: "#fff",
            fontSize: "1.5rem",
            cursor: "pointer",
            marginLeft: sidebarOpen ? "180px" : "10px",
          }}
        >
          ☰
        </button>
        <nav
          style={{
            marginTop: "30px",
            display: "flex",
            flexDirection: "column",
            gap: "15px",
            paddingLeft: sidebarOpen ? "20px" : "5px",
          }}
        >
          <span style={{ cursor: "pointer" }} onClick={() => setActiveTab("Candidates")}>
            👤 Candidates
          </span>
          <span style={{ cursor: "pointer" }} onClick={() => setActiveTab("Results")}>
            📊 Results
          </span>
          <span
            style={{ cursor: "pointer" }}
            onClick={() => setActiveTab("RegisterCandidacy")}
          >
            📝 Register Candidacy
          </span>
          <button
            onClick={() => {
              logout();
              navigate("/login");
            }}
            style={{
              marginTop: "auto",
              background: "#dc3545",
              color: "#fff",
              border: "none",
              padding: "10px",
              borderRadius: "6px",
              cursor: "pointer",
              fontWeight: "bold",
            }}
          >
            Logout
          </button>
        </nav>
      </aside>

      {/* Main */}
      <main
        style={{
          flexGrow: 1,
          padding: "30px",
          maxWidth: "1000px",
          margin: "0 auto",
        }}
      >
        {renderContent()}
      </main>
    </div>
  );
}
